def count_promising_substrings(s):
    n = len(s)
    count = 0
    for i in range(n):
        balance = 0
        for j in range(i, n):
            if s[j] == '+':
                balance += 1
            else:
                balance -= 1
            if balance < 0 and (j - i + 1) % 2 == 1:
                count += 1
    return count

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        s = input()
        results.append(count_promising_substrings(s))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
